// Package deepprint renders arbitrary Go values as deeply nested, readable
// text for debugging and inspection.
//
// Unlike fmt's %v and %+v, deepprint walks values with reflection to an
// unbounded depth and expands pointers, interfaces, structs, arrays, slices,
// maps, channels and funcs. Cycles in the object graph are detected and
// rendered as references instead of recursing forever, and map entries are
// sorted so that repeated dumps are stable.
//
// The package-level helpers use a default Printer:
//
//	deepprint.Dump(myValue)          // to stdout
//	s := deepprint.Sdump(myValue)    // to a string
//
// For finer control, configure a Printer directly:
//
//	p := deepprint.New(deepprint.Config{
//		Indent:       "  ",
//		MaxDepth:     6,
//		ShowPointers: true,
//	})
//	p.Dump(myValue)
package deepprint

import (
	"io"
	"os"
	"reflect"
	"strings"
)

// Config controls how a Printer renders values.
type Config struct {
	// Indent is the string written for each level of nesting. If empty,
	// two spaces are used.
	Indent string
	// MaxDepth limits how deep the walker descends. Zero means unlimited.
	// Once the limit is reached, a "..." placeholder is emitted in place of
	// the value.
	MaxDepth int
	// ShowTypes prefixes every value with its Go type, e.g. "(int) 42".
	ShowTypes bool
	// ShowPointers annotates pointers with their memory address.
	ShowPointers bool
	// ShowUnexported includes unexported struct fields in the output.
	ShowUnexported bool
	// SortMapKeys renders map entries ordered by their formatted key so that
	// output is deterministic across runs.
	SortMapKeys bool
}

// DefaultConfig returns a Config tuned for debugging: type information is on,
// unexported fields are included, and map keys are sorted for stable output.
func DefaultConfig() Config {
	return Config{
		Indent:         "  ",
		MaxDepth:       0,
		ShowTypes:      true,
		ShowPointers:   false,
		ShowUnexported: true,
		SortMapKeys:    true,
	}
}

// Printer renders values according to its Config.
type Printer struct {
	cfg Config
}

// New returns a Printer using cfg. A zero Indent falls back to two spaces.
func New(cfg Config) *Printer {
	if cfg.Indent == "" {
		cfg.Indent = "  "
	}
	return &Printer{cfg: cfg}
}

var defaultPrinter = New(DefaultConfig())

// Sdump renders v to a string. Multiple values are rendered one per line.
func (p *Printer) Sdump(v ...any) string {
	parts := make([]string, len(v))
	for i := range v {
		parts[i] = p.formatValue(reflect.ValueOf(v[i]))
	}
	return strings.Join(parts, "\n")
}

// Fdump renders v to w, followed by a newline.
func (p *Printer) Fdump(w io.Writer, v ...any) error {
	if _, err := io.WriteString(w, p.Sdump(v...)); err != nil {
		return err
	}
	_, err := io.WriteString(w, "\n")
	return err
}

// Dump renders v to standard output.
func (p *Printer) Dump(v ...any) error {
	return p.Fdump(os.Stdout, v...)
}

// Sdump renders v to a string using the default Printer.
func Sdump(v ...any) string { return defaultPrinter.Sdump(v...) }

// Fdump renders v to w using the default Printer.
func Fdump(w io.Writer, v ...any) error { return defaultPrinter.Fdump(w, v...) }

// Dump renders v to standard output using the default Printer.
func Dump(v ...any) error { return defaultPrinter.Dump(v...) }

package deepprint

import (
	"bytes"
	"math"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// visit identifies a reference value by its type and address, used for cycle
// detection while walking the object graph.
type visit struct {
	typ reflect.Type
	ptr uintptr
}

func (p *Printer) formatValue(v reflect.Value) string {
	var b bytes.Buffer
	p.writeValue(&b, v, 0, make(map[visit]bool))
	return b.String()
}

func (p *Printer) writeIndent(b *bytes.Buffer, depth int) {
	for i := 0; i < depth; i++ {
		b.WriteString(p.cfg.Indent)
	}
}

// writePrefix emits the value's type when ShowTypes is enabled.
func (p *Printer) writePrefix(b *bytes.Buffer, v reflect.Value) {
	if !p.cfg.ShowTypes {
		return
	}
	b.WriteByte('(')
	b.WriteString(v.Type().String())
	b.WriteString(") ")
}

func (p *Printer) writeValue(b *bytes.Buffer, v reflect.Value, depth int, seen map[visit]bool) {
	if !v.IsValid() {
		b.WriteString("<nil>")
		return
	}
	if p.cfg.MaxDepth > 0 && depth >= p.cfg.MaxDepth {
		b.WriteString("...")
		return
	}

	switch v.Kind() {
	case reflect.Bool:
		p.writePrefix(b, v)
		b.WriteString(strconv.FormatBool(v.Bool()))

	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		p.writePrefix(b, v)
		b.WriteString(strconv.FormatInt(v.Int(), 10))

	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		p.writePrefix(b, v)
		b.WriteString(strconv.FormatUint(v.Uint(), 10))

	case reflect.Uintptr:
		p.writePrefix(b, v)
		b.WriteString("0x")
		b.WriteString(strconv.FormatUint(v.Uint(), 16))

	case reflect.Float32, reflect.Float64:
		p.writePrefix(b, v)
		b.WriteString(formatFloat(v.Float(), v.Type().Bits()))

	case reflect.Complex64, reflect.Complex128:
		bits := v.Type().Bits() / 2
		c := v.Complex()
		p.writePrefix(b, v)
		b.WriteByte('(')
		b.WriteString(formatFloat(real(c), bits))
		b.WriteByte('+')
		b.WriteString(formatFloat(imag(c), bits))
		b.WriteString("i)")

	case reflect.String:
		p.writePrefix(b, v)
		b.WriteString(strconv.Quote(v.String()))

	case reflect.Ptr:
		p.writePointer(b, v, depth, seen)

	case reflect.Interface:
		if v.IsNil() {
			p.writePrefix(b, v)
			b.WriteString("<nil>")
			return
		}
		p.writeValue(b, v.Elem(), depth+1, seen)

	case reflect.Struct:
		p.writeStruct(b, v, depth, seen)

	case reflect.Map:
		p.writeMap(b, v, depth, seen)

	case reflect.Slice:
		p.writeSlice(b, v, depth, seen)

	case reflect.Array:
		p.writeArray(b, v, depth, seen)

	case reflect.Chan:
		p.writePrefix(b, v)
		if v.IsNil() {
			b.WriteString("<nil>")
			return
		}
		b.WriteString("0x")
		b.WriteString(strconv.FormatUint(uint64(v.Pointer()), 16))
		b.WriteString(" (len=")
		b.WriteString(strconv.Itoa(v.Len()))
		b.WriteString(" cap=")
		b.WriteString(strconv.Itoa(v.Cap()))
		b.WriteByte(')')

	case reflect.Func:
		p.writePrefix(b, v)
		if v.IsNil() {
			b.WriteString("<nil>")
			return
		}
		b.WriteString("<func>")

	case reflect.UnsafePointer:
		p.writePrefix(b, v)
		if v.Pointer() == 0 {
			b.WriteString("<nil>")
			return
		}
		b.WriteString("0x")
		b.WriteString(strconv.FormatUint(uint64(v.Pointer()), 16))

	default:
		b.WriteString("<unsupported ")
		b.WriteString(v.Kind().String())
		b.WriteByte('>')
	}
}

func (p *Printer) writePointer(b *bytes.Buffer, v reflect.Value, depth int, seen map[visit]bool) {
	if v.IsNil() {
		p.writePrefix(b, v)
		b.WriteString("<nil>")
		return
	}
	key := visit{v.Type(), v.Pointer()}
	if seen[key] {
		p.writePrefix(b, v)
		b.WriteString("<already shown>")
		return
	}
	seen[key] = true
	defer delete(seen, key)

	if p.cfg.ShowPointers {
		b.WriteString("0x")
		b.WriteString(strconv.FormatUint(uint64(v.Pointer()), 16))
		b.WriteByte(' ')
	}
	b.WriteByte('&')
	p.writeValue(b, v.Elem(), depth+1, seen)
}

func (p *Printer) writeStruct(b *bytes.Buffer, v reflect.Value, depth int, seen map[visit]bool) {
	t := v.Type()
	fields := make([]int, 0, v.NumField())
	for i := 0; i < v.NumField(); i++ {
		if !t.Field(i).IsExported() && !p.cfg.ShowUnexported {
			continue
		}
		fields = append(fields, i)
	}

	p.writePrefix(b, v)
	if len(fields) == 0 {
		b.WriteString("{}")
		return
	}
	b.WriteString("{\n")
	for _, i := range fields {
		p.writeIndent(b, depth+1)
		b.WriteString(t.Field(i).Name)
		b.WriteString(": ")
		p.writeValue(b, v.Field(i), depth+1, seen)
		b.WriteString(",\n")
	}
	p.writeIndent(b, depth)
	b.WriteByte('}')
}

func (p *Printer) writeMap(b *bytes.Buffer, v reflect.Value, depth int, seen map[visit]bool) {
	if v.IsNil() {
		p.writePrefix(b, v)
		b.WriteString("<nil>")
		return
	}
	key := visit{v.Type(), v.Pointer()}
	if seen[key] {
		p.writePrefix(b, v)
		b.WriteString("<already shown>")
		return
	}
	seen[key] = true
	defer delete(seen, key)

	p.writePrefix(b, v)
	if v.Len() == 0 {
		b.WriteString("{}")
		return
	}

	type entry struct {
		key string
		val reflect.Value
	}
	entries := make([]entry, 0, v.Len())
	iter := v.MapRange()
	for iter.Next() {
		var kb bytes.Buffer
		p.writeValue(&kb, iter.Key(), depth+1, make(map[visit]bool))
		entries = append(entries, entry{key: kb.String(), val: iter.Value()})
	}
	if p.cfg.SortMapKeys {
		sort.SliceStable(entries, func(i, j int) bool { return entries[i].key < entries[j].key })
	}

	b.WriteString("{\n")
	for _, e := range entries {
		p.writeIndent(b, depth+1)
		b.WriteString(e.key)
		b.WriteString(": ")
		p.writeValue(b, e.val, depth+1, seen)
		b.WriteString(",\n")
	}
	p.writeIndent(b, depth)
	b.WriteByte('}')
}

func (p *Printer) writeSlice(b *bytes.Buffer, v reflect.Value, depth int, seen map[visit]bool) {
	if v.IsNil() {
		p.writePrefix(b, v)
		b.WriteString("<nil>")
		return
	}
	if v.Len() > 0 {
		key := visit{v.Type(), v.Pointer()}
		if seen[key] {
			p.writePrefix(b, v)
			b.WriteString("<already shown>")
			return
		}
		seen[key] = true
		defer delete(seen, key)
	}

	if v.Type().Elem().Kind() == reflect.Uint8 {
		p.writePrefix(b, v)
		b.WriteString(formatBytes(v.Bytes()))
		return
	}

	p.writePrefix(b, v)
	b.WriteString("(len=")
	b.WriteString(strconv.Itoa(v.Len()))
	b.WriteString(" cap=")
	b.WriteString(strconv.Itoa(v.Cap()))
	b.WriteString(") ")
	p.writeIndexed(b, v, depth, seen)
}

func (p *Printer) writeArray(b *bytes.Buffer, v reflect.Value, depth int, seen map[visit]bool) {
	p.writePrefix(b, v)
	p.writeIndexed(b, v, depth, seen)
}

func (p *Printer) writeIndexed(b *bytes.Buffer, v reflect.Value, depth int, seen map[visit]bool) {
	if v.Len() == 0 {
		b.WriteString("{}")
		return
	}
	b.WriteString("{\n")
	for i := 0; i < v.Len(); i++ {
		p.writeIndent(b, depth+1)
		b.WriteString(strconv.Itoa(i))
		b.WriteString(": ")
		p.writeValue(b, v.Index(i), depth+1, seen)
		b.WriteString(",\n")
	}
	p.writeIndent(b, depth)
	b.WriteByte('}')
}

func formatFloat(f float64, bits int) string {
	switch {
	case math.IsNaN(f):
		return "NaN"
	case math.IsInf(f, 1):
		return "+Inf"
	case math.IsInf(f, -1):
		return "-Inf"
	}
	return strconv.FormatFloat(f, 'g', -1, bits)
}

func formatBytes(b []byte) string {
	if len(b) == 0 {
		return "[]byte{}"
	}
	if utf8.Valid(b) {
		return "[]byte(" + strconv.Quote(string(b)) + ")"
	}
	var sb strings.Builder
	sb.WriteString("[]byte{")
	for i, c := range b {
		if i > 0 {
			sb.WriteString(", ")
		}
		sb.WriteString("0x")
		if c < 0x10 {
			sb.WriteByte('0')
		}
		sb.WriteString(strconv.FormatUint(uint64(c), 16))
	}
	sb.WriteByte('}')
	return sb.String()
}

package deepprint

import (
	"bytes"
	"strings"
	"testing"
)

type point struct {
	X, Y int
}

type secret struct {
	Public  string
	private int
}

type node struct {
	Name string
	Next *node
}

func TestScalars(t *testing.T) {
	cases := []struct {
		name string
		in   any
		want string
	}{
		{"nil", nil, "<nil>"},
		{"bool", true, "(bool) true"},
		{"int", -42, "(int) -42"},
		{"uint", uint8(200), "(uint8) 200"},
		{"float", 1.5, "(float64) 1.5"},
		{"inf", inf(), "(float64) +Inf"},
		{"string", "hi\n", `(string) "hi\n"`},
		{"interface", any(7), "(int) 7"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := Sdump(tc.in); got != tc.want {
				t.Fatalf("Sdump(%v) = %q, want %q", tc.in, got, tc.want)
			}
		})
	}
}

func inf() float64 {
	var f float64 = 1
	return f / zero
}

var zero float64

func TestStruct(t *testing.T) {
	got := Sdump(point{X: 1, Y: 2})
	want := "(deepprint.point) {\n" +
		"  X: (int) 1,\n" +
		"  Y: (int) 2,\n" +
		"}"
	if got != want {
		t.Fatalf("got:\n%s\nwant:\n%s", got, want)
	}
}

func TestUnexportedFields(t *testing.T) {
	in := secret{Public: "a", private: 7}

	with := Sdump(in)
	if !strings.Contains(with, "private: (int) 7") {
		t.Fatalf("expected unexported field, got:\n%s", with)
	}

	p := New(Config{ShowTypes: true, ShowUnexported: false})
	without := p.Sdump(in)
	if strings.Contains(without, "private") {
		t.Fatalf("unexpected unexported field, got:\n%s", without)
	}
}

func TestPointerCycle(t *testing.T) {
	a := &node{Name: "a"}
	b := &node{Name: "b", Next: a}
	a.Next = b

	got := Sdump(a)
	if !strings.Contains(got, "</already shown>") && !strings.Contains(got, "<already shown>") {
		t.Fatalf("expected cycle marker, got:\n%s", got)
	}
	if strings.Count(got, `Name: (string) "a"`) != 1 {
		t.Fatalf("expected node a rendered once, got:\n%s", got)
	}
}

func TestMapDeterministic(t *testing.T) {
	m := map[string]int{"b": 2, "a": 1, "c": 3}
	got := Sdump(m)
	want := "(map[string]int) {\n" +
		"  (string) \"a\": (int) 1,\n" +
		"  (string) \"b\": (int) 2,\n" +
		"  (string) \"c\": (int) 3,\n" +
		"}"
	if got != want {
		t.Fatalf("got:\n%s\nwant:\n%s", got, want)
	}
}

func TestSliceAndArray(t *testing.T) {
	slice := Sdump([]int{4, 5})
	wantSlice := "([]int) (len=2 cap=2) {\n  0: (int) 4,\n  1: (int) 5,\n}"
	if slice != wantSlice {
		t.Fatalf("slice got:\n%s\nwant:\n%s", slice, wantSlice)
	}

	arr := Sdump([2]int{6, 7})
	wantArr := "([2]int) {\n  0: (int) 6,\n  1: (int) 7,\n}"
	if arr != wantArr {
		t.Fatalf("array got:\n%s\nwant:\n%s", arr, wantArr)
	}
}

func TestByteSlice(t *testing.T) {
	if got := Sdump([]byte("hi")); !strings.Contains(got, `[]byte("hi")`) {
		t.Fatalf("got %q", got)
	}
	if got := Sdump([]byte{0x00, 0xff}); !strings.Contains(got, "0x00") || !strings.Contains(got, "0xff") {
		t.Fatalf("got %q", got)
	}
}

func TestMaxDepth(t *testing.T) {
	p := New(Config{Indent: "  ", MaxDepth: 1, ShowTypes: true})
	got := p.Sdump(point{X: 1, Y: 2})
	want := "(deepprint.point) {\n  X: ...,\n  Y: ...,\n}"
	if got != want {
		t.Fatalf("got:\n%s\nwant:\n%s", got, want)
	}
}

func TestMultipleValues(t *testing.T) {
	got := Sdump(1, "x")
	want := "(int) 1\n(string) \"x\""
	if got != want {
		t.Fatalf("got %q, want %q", got, want)
	}
}

func TestFdump(t *testing.T) {
	var buf bytes.Buffer
	if err := Fdump(&buf, 1); err != nil {
		t.Fatal(err)
	}
	if got, want := buf.String(), "(int) 1\n"; got != want {
		t.Fatalf("got %q, want %q", got, want)
	}
}

